import re
from math import floor

lines = open('/app/text.gcode').read().splitlines()

cur = None
last_e = {}
segs = {0: [], 1: []}

for i, line in enumerate(lines, 1):
    if line.startswith('M486 S'):
        v = int(line.split()[-1])
        cur = None if v == -1 else v
        continue
    if cur not in (0, 1):
        continue
    m = re.match(r'^(G0|G1)\s+.*?(X[-+.\d]+)?.*?(Y[-+.\d]+)?.*?(E[-+.\d]+)?', line)
    if not m:
        continue
    # More robust: use word tokens
    vals = {'X': None, 'Y': None, 'E': None, 'Z': None}
    for tok in line.split()[1:]:
        if len(tok) >= 2 and tok[0] in vals:
            try: vals[tok[0]] = float(tok[1:])
            except ValueError: pass
    if vals['X'] is None or vals['Y'] is None or vals['E'] is None:
        continue
    last = last_e.get(cur, 0.0)
    if abs(vals['E'] - last) > 1e-9:
        segs[cur].append((vals['X'], vals['Y'], vals['E']))
        last_e[cur] = vals['E']
    else:
        # leave last_e unchanged if travel with no E; if E is relative? just track
        pass

for obj in (0, 1):
    if not segs[obj]:
        continue
    xs = [p[0] for p in segs[obj]]
    ys = [p[1] for p in segs[obj]]
    print('OBJECT', obj, 'segments', len(segs[obj]), 'bbox', min(xs), max(xs), min(ys), max(ys))
    print(segs[obj][:20])
